            else:
                result.update(verdict='roll_forward', offer_date=rolled)
        elif amount < floor:
            result.update(verdict='below_floor', offer_amount='%.2f' % floor)
        elif amount > full:
            result.update(verdict='above_full', offer_amount='%.2f' % full)
        return result
    except Exception:
        return dict(verdict='unreadable')
