def _save(s):
    vars['state_json'] = json.dumps(s)

def _empty(name):
    return EMPTY.get(name, '')

def _get(name):
    v = _str(vars.get(name)).strip()
    if v == _str(_empty(name)) or v == 'none':
        return ''
    try:
        if _empty(name) == 0 and float(v) == 0:
            return ''
    except Exception:
        pass
    return v

def _clear(*names):
    for n in names:
        vars[n] = _empty(n)

def _int(x):
    try:
        return int(float(_str(x)))
    except Exception:
        return None

def _float(x):
    try:
        v = float(_str(x).replace(',', ''))
        return v
    except Exception:
        return None

def _money(x):
    try:
        return '%.2f' % float(x)
    except Exception:
        return _str(x)

def _fmt(iso):
    try:
        d = datetime.date.fromisoformat(_str(iso)[:10])
        return d.strftime('%A') + ' ' + str(d.day) + ' ' + d.strftime('%B %Y')
    except Exception:
        return _str(iso)

def _cal():
    c = POLICY['calendar']
    return (c['holidays'], c['business_days'])

def _calendar_dict():
